cypress_script:
describe('Checkout Information Form', () => {
  it('should navigate to checkout information form and submit with valid data', () => {
    cy.visit('https://www.saucedemo.com/checkout-step-one.html');
    cy.get('[data-test="firstName"]').type('John');
    cy.get('[data-test="lastName"]').type('Doe');
    cy.get('[data-test="postalCode"]').type('12345');
    cy.get('[data-test="continue"]').click();
    cy.url().should('not.include', 'checkout-step-one.html');
  });

  it('should not submit the form with empty fields', () => {
    cy.visit('https://www.saucedemo.com/checkout-step-one.html');
    cy.get('[data-test="continue"]').click();
    cy.url().should('include', 'checkout-step-one.html');
    cy.get('[data-test="firstName"]').should('be.visible');
    cy.get('[data-test="lastName"]').should('be.visible');
    cy.get('[data-test="postalCode"]').should('be.visible');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Checkout Information Form', () => {
  test('should navigate to checkout information form and submit with valid data', async ({ page }) => {
    await page.goto('https://www.saucedemo.com/checkout-step-one.html');
    await page.fill('[data-test="firstName"]', 'John');
    await page.fill('[data-test="lastName"]', 'Doe');
    await page.fill('[data-test="postalCode"]', '12345');
    await page.click('[data-test="continue"]');
    await expect(page.url()).not.toContain('checkout-step-one.html');
  });

  test('should not submit the form with empty fields', async ({ page }) => {
    await page.goto('https://www.saucedemo.com/checkout-step-one.html');
    await page.click('[data-test="continue"]');
    await expect(page.url()).toContain('checkout-step-one.html');
    await expect(page.locator('[data-test="firstName"]').isVisible());
    await expect(page.locator('[data-test="lastName"]').isVisible());
    await expect(page.locator('[data-test="postalCode"]').isVisible());
  });
});
